            i += 2
            continue
        if ch == in_string:
            in_string = None
        i += 1
        continue

    # Check comments and strings
    if ch == '/' and i + 1 < n and code[i+1] == '/':
        in_line_comment = True
        i += 2
        continue
    if ch == '/' and i + 1 < n and code[i+1] == '*':
