"/* Linux Mint Cinnamon 22.3 Desktop Simulator Styles (Mint-Y Authentic Theme) */
:root {
  --mint-green: #87bd5c;
  --mint-green-light: #9ad46f;
  --mint-green-dark: #6e9f47;
  --mint-green-glow: rgba(135, 189, 92, 0.35);
  --mint-accent: #2ecc71;
  --cinnamon-panel: #262a30;
  --cinnamon-panel-dark: #1e2126;
  --window-bg: #202428;
  --window-title: #2b3036;
  --window-border: #383f47;
  --text-main: #f0f3f5;
  --text-muted: #9aa0a6;
  --danger: #e74c3c;
  --warning: #f39c12;
  --mint-y-btn-hover: rgba(255, 255, 255, 0.12);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Ubuntu", "Noto Sans", "Segoe UI", Roboto, sans-serif;
  user-select: none;
}

body, html {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background-color: #0c0e10;
}

/* ==================== DESKTOP CANVAS & AUTHENTIC MINT WALLPAPER ==================== */
#desktop {
  width: 100vw;
  height: calc(100vh - 42px);
  position: relative;
  background: radial-gradient(circle at 50% 45%, #242c26 0%, #151b18 55%, #0b0e0d 100%);
  background-size: cover;
  background-position: center;
  overflow: hidden;
}

/* Authentic Centered Embossed Linux Mint Wallpaper Emblem */
.mint-desktop-center-logo {
  position: absolute;
  top: 45%;
  left: 50%;
  transform: translate(-50%, -50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  pointer-events: none;
  opacity: 0.22;
  transition: opacity 0.3s;
}

.mint-desktop-center-logo svg {
  width: 220px;
  height: 220px;
  filter: drop-shadow(0 14px 40px rgba(0, 0, 0, 0.85));
}

.mint-desktop-center-logo h1 {
  font-size: 2.2rem;
  font-weight: 800;
  color: #fff;
  letter-spacing: 2.5px;
  margin-top: 14px;
  text-shadow: 0 4px 12px rgba(0, 0, 0, 0.9);
}

.mint-desktop-center-logo p {
  font-size: 0.92rem;
  color: var(--mint-green);
  font-weight: 600;
  letter-spacing: 1.5px;
  margin-top: 4px;
  text-shadow: 0 2px 8px rgba(0, 0, 0, 0.8);
}
